"""Reproduce signal-v3-vector.json independently of PHP and Node.js.

Test-only fixed keys. Implements the Signal v3 X3DH/ratchet derivation and wire
format using Python cryptography (OpenSSL) and hashlib/hmac. This file is fixture
tooling; it is neither imported nor required by the PHP library or test runner.
"""
from pathlib import Path
import hashlib
import hmac
import json
from cryptography.hazmat.primitives.asymmetric.x25519 import X25519PrivateKey
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.padding import PKCS7


def mac(key, message):
    return hmac.new(key, message, hashlib.sha256).digest()


def hkdf(ikm, info, length, salt=b"\0" * 32):
    prk = mac(salt, ikm)
    block = out = b""
    for counter in range(1, (length + 31) // 32 + 1):
        block = mac(prk, block + info + bytes([counter]))
        out += block
    return out[:length]


def pair(seed):
    private = bytes((seed + i) % 256 for i in range(32))
    key = X25519PrivateKey.from_private_bytes(private)
    return private, b"\x05" + key.public_key().public_bytes_raw()


def dh(private, public):
    from cryptography.hazmat.primitives.asymmetric.x25519 import X25519PublicKey
    return X25519PrivateKey.from_private_bytes(private).exchange(X25519PublicKey.from_public_bytes(public[1:]))


def varint(n):
    result = b""
    while n >= 128:
        result += bytes([(n & 127) | 128])
        n >>= 7
    return result + bytes([n])


def blob(field, value):
    return varint(field * 8 + 2) + varint(len(value)) + value


def uint(field, value):
    return varint(field * 8) + varint(value)


ai, base, ratchet = pair(1), pair(33), pair(65)
bi, signed, one_time = pair(97), pair(129), pair(161)
secret = b"\xff" * 32 + dh(ai[0], signed[1]) + dh(base[0], bi[1]) + dh(base[0], signed[1]) + dh(base[0], one_time[1])
initial = hkdf(secret, b"WhisperText", 64)
send = hkdf(dh(ratchet[0], signed[1]), b"WhisperRatchet", 64, initial[:32])
expanded = hkdf(mac(send[32:], b"\x01"), b"WhisperMessageKeys", 80)
plaintext = b"\x0a\x0cHello Signal\x00\xff"
padder = PKCS7(128).padder()
padded = padder.update(plaintext) + padder.finalize()
encryptor = Cipher(algorithms.AES(expanded[:32]), modes.CBC(expanded[64:80])).encryptor()
ciphertext = encryptor.update(padded) + encryptor.finalize()
inner = b"\x33" + blob(1, ratchet[1]) + uint(2, 0) + uint(3, 0) + blob(4, ciphertext)
inner += mac(expanded[32:64], ai[1] + bi[1] + inner)[:8]
outer = b"\x33" + uint(1, 23) + blob(2, base[1]) + blob(3, ai[1]) + blob(4, inner) + uint(5, 12345) + uint(6, 17)
result = {
    "provenance": "Independent Python cryptography/OpenSSL + hashlib/hmac, generated by generate-signal-vector.py. All keys are public test fixtures.",
    "aliceIdentityPrivate": ai[0].hex(), "aliceIdentityPublic": ai[1].hex(),
    "aliceBasePrivate": base[0].hex(), "aliceBasePublic": base[1].hex(),
    "aliceRatchetPrivate": ratchet[0].hex(), "aliceRatchetPublic": ratchet[1].hex(),
    "bobIdentityPrivate": bi[0].hex(), "bobIdentityPublic": bi[1].hex(),
    "bobSignedPrivate": signed[0].hex(), "bobSignedPublic": signed[1].hex(),
    "bobPreKeyPrivate": one_time[0].hex(), "bobPreKeyPublic": one_time[1].hex(),
    "initialRoot": initial[:32].hex(), "initialChain": initial[32:].hex(),
    "sendRoot": send[:32].hex(), "sendChain": send[32:].hex(),
    "nextChain": mac(send[32:], b"\x02").hex(),
    "cipherKey": expanded[:32].hex(), "macKey": expanded[32:64].hex(), "iv": expanded[64:80].hex(),
    "plaintext": plaintext.hex(), "signalMessage": inner.hex(), "preKeySignalMessage": outer.hex(),
}
Path(__file__).with_name("signal-v3-vector.json").write_text(json.dumps(result, indent=2) + "\n", encoding="utf-8")
